let MUTE=(()=>{try{return localStorage.getItem("ta_mute")==="1"}catch(e){return false}})(),AC;
const tone=(f,d=.12,t="sine",v=.12,w=0)=>{if(MUTE)return;try{AC=AC||new (window.AudioContext||window.webkitAudioContext)();const o=AC.createOscillator(),g=AC.createGain(),s=AC.currentTime+w;o.type=t;o.frequency.value=f;g.gain.setValueAtTime(v,s);g.gain.exponentialRampToValueAtTime(.001,s+d);o.connect(g);g.connect(AC.destination);o.start(s);o.stop(s+d)}catch(e){}};
const sfx={tick:()=>tone(660,.05,"square",.05),ok:()=>{tone(523,.12,"triangle",.16);tone(784,.22,"triangle",.16,.1)},bad:()=>{tone(220,.25,"sawtooth",.12);tone(165,.3,"sawtooth",.12,.15)},win:()=>[523,659,784,1047].forEach((f,k)=>tone(f,.22,"triangle",.16,k*.12))};
if(typeof document!=="undefined"&&!window.__taTick){window.__taTick=1;document.addEventListener("click",e=>{if(e.target.closest&&e.target.closest("button,a"))sfx.tick()})}
let STAGE="M";const STG={P:"P",M:"M",S:"S",A1:"P",A2:"M",B1:"S",B2:"S"};
const F=db=>{if(db!==VERBS_DB)return db;const L=(VL[CURG]||"").split(","),f=db.filter(v=>L.includes(v.en));return f.length>=8?f:db};
const lc=s=>s==="I"||s==="Ali"?s:s.toLowerCase();
const speak=t=>{if(MUTE)return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(t).replace(/a\/an/g,"a").replace(/_+/g,", ").replace(/[=\/↔→←+|]/g," ").replace(/\s+/g," ").trim());u.lang="en-US";u.rate=.85;speechSynthesis.speak(u)}catch(e){}};
/* ============ ENGINE HELPERS ============ */
const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
const pick=(a,n)=>shuffle(a).slice(0,n);
const norm=s=>String(s).trim().toLowerCase();
const s3=v=>v==="have"?"has":/(s|sh|ch|x|o)$/.test(v)?v+"es":/[^aeiou]y$/.test(v)?v.slice(0,-1)+"ies":v+"s";
const mc=(prompt,promptAr,big,ans,pool,exp,expAr)=>({type:"mc",prompt,promptAr,big,opts:shuffle([ans,...pick([...new Set(pool)].filter(x=>x!==ans),3)]),ans,exp,expAr});
const ty=(prompt,promptAr,big,ans,exp,expAr,letters)=>({type:"ty",prompt,promptAr,big,ans,exp,expAr,letters});
/* ============ GAME GENERATORS ============ */
const meaning=db=>()=>ord(F(db),16).map((x,i)=>i%2?mc("Choose the English word","اختر الكلمة بالإنجليزية",(x.e||"")+" "+x.ar,x.en,samePos(x,db,"en"),`${x.ar} = ${x.en}`,`${x.ar} تعني ${x.en}`):mc("What does it mean?","ما معنى هذه الكلمة؟",(x.e||"")+" "+x.en,x.ar,samePos(x,db,"ar"),`${x.en} = ${x.ar}`,`${x.en} تعني ${x.ar}`));
const scramble=db=>()=>ord(F(db).filter(x=>!x.en.includes(" ")&&x.en.length>2),8).map(x=>{let a;do{a=shuffle(x.en.split(""))}while(a.join("")===x.en);return ty("Unscramble the word","رتّب الحروف لتكوين كلمة",(x.e||"")+" "+x.ar,x.en,`Correct spelling: ${x.en}`,`الإملاء الصحيح: ${x.en}`,a)});
const places=()=>[...new Set(JOBS_DB.map(j=>j.pl))];
const workplaces=()=>ord(JOBS_DB.filter(j=>!j.g),10).map(x=>mc(`Where does a ${x.en} work?`,`أين يعمل ${x.ar}؟`,x.e,x.pl,places(),`A ${x.en} works at the ${x.pl}.`,`${x.ar} يعمل في ${x.plAr}.`));
const opposites=pairs=>()=>ord(pairs,10).map(x=>mc(`What is the opposite of "${x.en}"?`,`ما عكس "${x.ar}"؟`,x.en.toUpperCase(),x.opp,pairs.length>=4?pairs.map(q=>q.opp):ALLOPP,`${x.en} ↔ ${x.opp}`,`${x.ar} ↔ ${x.oppAr}`));
const SUBJ=[["I",0],["You",0],["We",0],["They",0],["He",1],["She",1],["The teacher",1],["My friends",0],["Ali",1]];
